//! # `fix ave/spatial` against upstream (gh:#1418)
//!
//! ## Methodology
//!
//! Deck `reference-data/liggghts/in.avespatial` (generated by
//! `gen_avespatial.sh`; LIGGGHTS-PUBLIC `3d5c00f2`, `lmp_serial`): the settled
//! 354-pebble bed under tilted gravity `(0.6, 0, -0.8) * 9.81` for 2000 steps
//! (the `in.aveatom` bed), box `[-1,1]^2 x [-0.005,0.35]`, no periodicity, with
//! five `fix ave/spatial`:
//!
//! | fix | dims (origin delta) | values | norm | ave | bins x cols |
//! |---|---|---|---|---|---|
//! | `s1` | z lower 0.01 | vx vy vz density/number density/mass v_xv | all | one | 36 x 8 |
//! | `s2` | z lower 0.01 | vz density/mass v_xv | sample | running | 36 x 5 |
//! | `s3` | z lower 0.01 (10/3/50) | vx density/number | sample | window 2 | 36 x 4 |
//! | `s4` | z lower 0.01, x lower 1.0 | vz density/number | all | one | 72 x 5 |
//! | `s5` | z lower 0.01, x center 1.0, y lower 1.0 | density/mass vx v_xv | sample | one | 144 x 6 |
//!
//! `v_xv` is the atom-style variable `x*vz`. Thermo prints every
//! `f_ID[row][col]` (`%.17g`) at steps 0, 500, ..., 2000 (`avespatial_thermo.txt`,
//! 5 rows x 1836 values). The test runs the same bed in [`GranularSystem`] and
//! feeds [`AveSpatial`] the atoms in upstream's local order every step.
//!
//! ## Prediction (written before the run, 2026-11-11)
//!
//! Bed state is bit-identical (see `ave_time_cross_code.rs`), per-bin sums are
//! accumulated in the same atom order, and every normalisation is translated
//! operation for operation (including `*= mv2d/repeat`), so **all 9180 values
//! bit-identical**.
//!
//! ## Result
//!
//! 2026-11-11, rustc 1.99.1, release: **9180/9180 bit-identical**, worst relative difference 0.
//! Weakness: no periodic dimension, no `region`, no `units reduced` is exercised by upstream; those
//! branches are translated and unit-tested only.

use outram_park_fork_liggghts::boundary::Boundary;
use outram_park_fork_liggghts::diagnostics::{AveMode, AveSpatial, SpatialBox, SpatialDim, SpatialNorm, SpatialOrigin, SpatialValue};
use outram_park_fork_liggghts::granular::{GranularContactModel, GranularMaterial};
use outram_park_fork_liggghts::granular_system::GranularSystem;
use outram_park_fork_liggghts::neighbor_list::LiggghtsNeighbor;
use outram_park_fork_liggghts::particle::{Particle, Vec3};
use uom::si::f64::{Length, Mass, ThermodynamicTemperature};
use uom::si::{length::meter, mass::kilogram, thermodynamic_temperature::kelvin};

const REF: &str = include_str!("../../../reference-data/liggghts/avespatial_thermo.txt");

fn particles(csv: &str) -> Vec<Particle> {
    let r = 0.005;
    let mass = 2500.0 * 4.0 / 3.0 * std::f64::consts::PI * r * r * r;
    csv.lines()
        .skip(1)
        .filter(|l| !l.trim().is_empty())
        .map(|l| {
            let v: Vec<f64> = l.split(',').map(|x| x.parse().unwrap()).collect();
            Particle::new(
                Vec3::new(v[1], v[2], v[3]),
                Vec3::new(v[4], v[5], v[6]),
                Vec3::zero(),
                Mass::new::<kilogram>(mass),
                Length::new::<meter>(r),
                ThermodynamicTemperature::new::<kelvin>(300.0),
            )
            .unwrap()
        })
        .collect()
}

/// `fix gravity 9.81 vector 0.6 0 -0.8` as upstream forms it.
fn tilted_gravity() -> Vec3 {
    let (xd, zd): (f64, f64) = (0.6, -0.8);
    let length = (xd * xd + 0.0 * 0.0 + zd * zd).sqrt();
    Vec3::new(9.81 * (xd / length), 9.81 * (0.0 / length), 9.81 * (zd / length))
}

fn dim(axis: usize, origin: SpatialOrigin, delta: f64) -> SpatialDim {
    SpatialDim { axis, origin, delta }
}

fn feed(sys: &GranularSystem, step: i64, fixes: &mut [AveSpatial]) {
    let local = sys.particles_in_local_order();
    let x: Vec<[f64; 3]> = local.iter().map(|p| [p.position.x, p.position.y, p.position.z]).collect();
    let v: Vec<[f64; 3]> = local.iter().map(|p| [p.velocity.x, p.velocity.y, p.velocity.z]).collect();
    let f = vec![[0.0; 3]; x.len()];
    let rmass: Vec<f64> = local.iter().map(|p| p.mass).collect();
    // atom-style variable xv = x*vz
    let xv: Vec<f64> = local.iter().map(|p| p.position.x * p.velocity.z).collect();
    for a in fixes.iter_mut() {
        a.end_of_step(step, &x, &v, &f, &rmass, &[&xv], None);
    }
}

/// Five `fix ave/spatial` (1-d, 2-d, 3-d; `norm all/sample`; `ave
/// one/running/window`; `vx vy vz density/number density/mass v_` columns)
/// against the thermo dump of `in.avespatial`: **9180/9180 bit-identical** is
/// the pass criterion (5 rows x 1836 values, rows at steps 0, 500, ..., 2000).
#[test]
fn ave_spatial_matches_liggghts() {
    let Ok(init) = std::fs::read_to_string(
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../reference-data/liggghts/pebble_bed_settled.csv"),
    ) else {
        eprintln!("skipping: reference data not present");
        return;
    };
    let material = GranularMaterial::new(5.0e6, 0.3, 0.5, 0.3).unwrap();
    let mut sys = GranularSystem::new(
        particles(&init),
        vec![
            Boundary::cylinder(Vec3::zero(), Vec3::new(0.0, 0.0, 1.0), 0.030).unwrap(),
            Boundary::wall(Vec3::zero(), Vec3::new(0.0, 0.0, 1.0)).unwrap(),
        ],
        GranularContactModel::hertz_history(material),
        tilted_gravity(),
        5e-6,
    )
    .unwrap()
    .with_liggghts_neighbor_order(
        LiggghtsNeighbor::new(Vec3::new(-1.0, -1.0, -0.005), Vec3::new(1.0, 1.0, 0.35), 0.003).unwrap(),
    );
    let bx = SpatialBox { lo: [-1.0, -1.0, -0.005], hi: [1.0, 1.0, 0.35], periodic: [false; 3] };
    let z = dim(2, SpatialOrigin::Lower, 0.01);
    use SpatialValue::{Column, DensityMass as DM, DensityNumber as DN, V};
    let mut fixes = vec![
        AveSpatial::new(10, 5, 100, vec![z], vec![V(0), V(1), V(2), DN, DM, Column(0)], SpatialNorm::All, AveMode::One, bx, 0).unwrap(),
        AveSpatial::new(10, 5, 100, vec![z], vec![V(2), DM, Column(0)], SpatialNorm::Sample, AveMode::Running, bx, 0).unwrap(),
        AveSpatial::new(10, 3, 50, vec![z], vec![V(0), DN], SpatialNorm::Sample, AveMode::Window(2), bx, 0).unwrap(),
        AveSpatial::new(10, 5, 100, vec![z, dim(0, SpatialOrigin::Lower, 1.0)], vec![V(2), DN], SpatialNorm::All, AveMode::One, bx, 0).unwrap(),
        AveSpatial::new(
            10,
            5,
            100,
            vec![z, dim(0, SpatialOrigin::Center, 1.0), dim(1, SpatialOrigin::Lower, 1.0)],
            vec![DM, V(0), Column(0)],
            SpatialNorm::Sample,
            AveMode::One,
            bx,
            0,
        )
        .unwrap(),
    ];
    let ncols = [8usize, 5, 4, 5, 6];
    feed(&sys, 0, &mut fixes); // setup()
    let (mut done, mut total, mut same) = (0i64, 0usize, 0usize);
    let mut worst = 0.0f64;
    for row in REF.lines() {
        let c: Vec<&str> = row.split_whitespace().collect();
        let step: i64 = c[0].parse().unwrap();
        while done < step {
            sys.run(1);
            done += 1;
            feed(&sys, done, &mut fixes);
        }
        let mut k = 1;
        for (a, &nc) in fixes.iter().zip(ncols.iter()) {
            for i in 0..a.nbins() {
                for j in 0..nc {
                    let t: f64 = c[k].parse().unwrap();
                    k += 1;
                    total += 1;
                    let ours = a.array(i, j);
                    if ours.to_bits() == t.to_bits() {
                        same += 1;
                    } else {
                        worst = worst.max(((ours - t) / t).abs());
                        eprintln!("step {step} bin {i} col {j}: ours {ours:e} upstream {t:e}");
                    }
                }
            }
        }
        assert_eq!(k, c.len(), "column count mismatch");
    }
    eprintln!("ave/spatial: {same}/{total} values bit-identical (worst relative difference {worst:e})");
    assert_eq!(same, total);
}
